if (!function_exists('orc_steps')) {
  function orc_steps(int $id, int $step, bool $deliveryEnabled): void {
    $steps=[1=>'Dados do orçamento',2=>'Produtos/Serviços',3=>'Pagamento']; if($deliveryEnabled)$steps[4]='Entrega';
    echo '<nav class="orc-steps" aria-label="Etapas do orçamento">';
    foreach($steps as $n=>$label){$disabled=$id<=0&&$n>1; $href=$disabled?'#':'orcamento_editar.php'.($id>0?'?id='.$id.'&step='.$n:'?step=1'); echo '<a class="orc-step '.($step===$n?'active ':'').($disabled?'disabled':'').'" href="'.orc_e($href).'"><span class="orc-step-num">'.$n.'</span>'.orc_e($label).'</a>';}
    echo '</nav>';
  }
}
